INSERT INTO questions (exam_name, subject, topic, difficulty, question, options, correct_answer, explanation, language, question_hash, created_at) VALUES ('RRB Group D','Geography','Indian Geography','Hard','कथन (A): रेपो रेट ऋण दरों को प्रभावित करती है। कारण (R): रेपो रेट वह दर है जिस पर RBI वाणिज्यिक बैंकों को उधार देता है।','[''A और R दोनों सही हैं और R, A की सही व्याख्या है'', ''A और R दोनों सही हैं पर R, A की सही व्याख्या नहीं है'', ''A सही है पर R गलत है'', ''A गलत है पर R सही है'']','A और R दोनों सही हैं और R, A की सही व्याख्या है','Repo rate is a policy signal that propagates to loan pricing.','Hindi','f1fc7cad164c4db9796d5e066f884c2ac63e9deb72bfb82c93274d8de3006886','2026-05-01T05:44:55.638963+00:00');
